using AssetForge.Core.Models;using AssetForge.Infrastructure.Data;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;namespace AssetForge.Web.Pages.Assets;public class IndexModel(AssetForgeDbContext db):PageModel{public List<Asset> Assets{get;set;}=[];public string Search{get;set;}="";public string Status{get;set;}="";public async Task OnGetAsync(string? search,string? status){Search=search?.Trim()??"";Status=status??"";var q=db.Assets.Include(x=>x.Category).Include(x=>x.Location).Include(x=>x.Department).AsNoTracking();if(Search.Length>0)q=q.Where(x=>x.AssetTag.Contains(Search)||x.Name.Contains(Search)||(x.SerialNumber??"").Contains(Search));if(Status.Length>0)q=q.Where(x=>x.Status==Status);Assets=await q.OrderBy(x=>x.AssetTag).ToListAsync();}}
